"use client";

import { cn } from "@/lib/utils";
import { useCallback, useLayoutEffect, useRef } from "react";
import type { CSSProperties, ReactNode } from "react";

type AnimatedSegmentedToggleSize = "compact" | "default";

interface AnimatedSegmentedToggleOption {
  ariaLabel?: string;
  id: string;
  label: ReactNode;
}

interface AnimatedSegmentedToggleProps {
  animateSelection?: boolean;
  ariaLabel?: string;
  className?: string;
  onSelect: (id: string) => void;
  options: readonly AnimatedSegmentedToggleOption[];
  selectedId: string;
  size?: AnimatedSegmentedToggleSize;
}

// The container, option and
// thumb classes are the ones.
const containerClasses = {
  compact: "inline-grid gap-0.5 rounded-[10px] bg-panel-secondary/92 p-0.5",
  default: "bg-text/10 inline-grid gap-1 rounded-2xl p-1",
} as const satisfies Record<AnimatedSegmentedToggleSize, string>;

// `cursor-interaction` is `default` on the Electron desktop window.
const optionClasses = {
  compact:
    "flex h-6 items-center justify-center rounded-lg px-2 py-0 text-xs leading-4 font-medium focus:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0",
  default: "rounded-xl px-3 py-1.5 text-sm font-medium",
} as const satisfies Record<AnimatedSegmentedToggleSize, string>;

const selectedTextClasses = {
  compact: "text-text",
  default: "text-black",
} as const satisfies Record<AnimatedSegmentedToggleSize, string>;

const thumbClasses = {
  compact: "absolute inset-0 -z-10 rounded-lg bg-panel shadow-sm",
  default: "absolute inset-0 -z-10 rounded-xl bg-white shadow-sm",
} as const satisfies Record<AnimatedSegmentedToggleSize, string>;

// The thumb's layout animation, on the Web Animations API.
//
// The thumb is `<motion.span layoutId transition={{ type: "spring",
// duration: 0.28, bounce: 0 }}>`. Motion's shared layout animation runs one
// spring from 0 to 1000 and mixes the thumb from its old box to its new box
// with that progress. Both boxes have the same size (equal grid columns), so
// only the translation changes, linearly in the progress; the component never
// animates the thumb's opacity here.
//
// Motion resolves a spring from duration and bounce. With bounce 0 the
// damping ratio is 1 and the velocity 0. It finds the undamped frequency w by
// Newton's method (11 steps from 5 / duration) on
// exp(-w * duration) * (w * duration + 1) = 0.001, and the spring returns
// progress(t) = 1 - (1 + w * t) * exp(-w * t), snapping to 1 at the duration.
// Here that is w = 32.98 / s and a 280 ms animation. A keyframe every
// millisecond keeps the interpolation error below 0.02% of the travel.
//
// Measured in Chromium on /gallery/segmented-control: the thumb is within 0.01 px of this
// formula at every frame. Against motion 14.9.0 running the same markup the
// curve is the same; from rest this version starts at the first frame after the
// click, motion one frame later (0 to 16.2 ms, under one 60 Hz frame), and
// when a click interrupts a move both restart from rest at the thumb's
// current position and start together within 2 ms.
const SPRING_DURATION_SECONDS = 0.28;
const SPRING_REST_DELTA = 0.001;
const SPRING_NEWTON_STEPS = 11;
const SPRING_SAMPLES = 280;
const MILLISECONDS = 1000;

const springFrequency = () => {
  let x = 5;

  for (let step = 0; step < SPRING_NEWTON_STEPS; step += 1) {
    const decay = Math.exp(-x);

    x -= (decay * (1 + x) - SPRING_REST_DELTA) / (-x * decay);
  }

  return x / SPRING_DURATION_SECONDS;
};

const frequency = springFrequency();

// Position of a critically damped spring released at rest, from 0 to 1.
const springProgress = (seconds: number) =>
  1 - (1 + frequency * seconds) * Math.exp(-frequency * seconds);

const springKeyframes = (dx: number, dy: number): Keyframe[] =>
  Array.from({ length: SPRING_SAMPLES + 1 }, (_, index) => {
    const remaining =
      1 - springProgress((index / SPRING_SAMPLES) * SPRING_DURATION_SECONDS);

    return { transform: `translate(${dx * remaining}px, ${dy * remaining}px)` };
  });

const AnimatedSegmentedToggle = ({
  animateSelection = true,
  ariaLabel,
  className,
  onSelect,
  options,
  selectedId,
  size = "default",
}: AnimatedSegmentedToggleProps) => {
  const thumbRef = useRef<HTMLSpanElement | null>(null);
  const previousRect = useRef<DOMRect | null>(null);
  const animationRef = useRef<Animation | null>(null);

  // layoutId: the thumb is one shared element, so a new selection moves it
  // from where the old one is drawn to where the new one is. The thumb is
  // remounted in the newly selected option; its ref cleanup runs while the
  // old thumb is still in the document, so for every selection change,
  // whether from a click or from the parent, the start is the position the
  // thumb is drawn at now, also while it is still moving.
  // A ref callback that returns a cleanup is never called with null.
  const attachThumb = useCallback((thumb: HTMLSpanElement) => {
    thumbRef.current = thumb;

    return () => {
      previousRect.current = thumb.getBoundingClientRect();
      thumbRef.current = null;
    };
  }, []);

  useLayoutEffect(() => {
    const thumb = thumbRef.current;

    if (!thumb) {
      return;
    }

    const from = previousRect.current;
    const to = thumb.getBoundingClientRect();

    previousRect.current = null;
    animationRef.current?.cancel();
    animationRef.current = null;

    if (animateSelection && from) {
      const dx = from.left - to.left;
      const dy = from.top - to.top;

      if (dx !== 0 || dy !== 0) {
        animationRef.current = thumb.animate(springKeyframes(dx, dy), {
          duration: SPRING_DURATION_SECONDS * MILLISECONDS,
          easing: "linear",
        });
      }
    }

    // The effect runs when the selection changes; the thumb is read from the ref.
    // oxlint-disable-next-line react/exhaustive-effect-dependencies
  }, [animateSelection, selectedId]);

  const columnsStyle: CSSProperties & Record<`--${string}`, string> = {
    "--columns": String(options.length),
  };

  return (
    <div
      aria-label={ariaLabel}
      className={cn(
        containerClasses[size],
        "[grid-template-columns:repeat(var(--columns),minmax(0,1fr))]",
        className
      )}
      // The group is <div role="group" aria-label>.
      // oxlint-disable-next-line jsx-a11y/prefer-tag-over-role
      role="group"
      style={columnsStyle}
    >
      {options.map((option) => {
        const selected = option.id === selectedId;

        return (
          <button
            aria-label={option.ariaLabel}
            aria-pressed={selected}
            className={cn(
              "relative isolate min-w-0 cursor-default transition-transform duration-(--motion-duration-fast) active:scale-[0.98]",
              optionClasses[size],
              selected ? selectedTextClasses[size] : "text-text-muted"
            )}
            key={option.id}
            onClick={() => {
              onSelect(option.id);
            }}
            type="button"
          >
            {selected ? (
              <span className={thumbClasses[size]} ref={attachThumb} />
            ) : null}
            {option.label}
          </button>
        );
      })}
    </div>
  );
};

export { AnimatedSegmentedToggle };

export type {
  AnimatedSegmentedToggleOption,
  AnimatedSegmentedToggleProps,
  AnimatedSegmentedToggleSize,
};

"use client";

// Lucide artwork is covered by components/icon/lucide.license.

/* oxlint-disable shadcn/no-restyle, shadcn/no-arbitrary-values, shadcn/require-static-classes -- The coachmark surface is an unstyled popover with measured values that have no theme token (the coachmark colours, the 36 x 14 arrow). */
import { Popover } from "@base-ui/react/popover";
import { createIcon } from "@/components/icon";
import { useEffect } from "react";
import type { ReactNode } from "react";

const CloseIcon = createIcon({
  body: '<g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18"></path><path d="m6 6 12 12"></path></g>',
  canvas: { height: 16, viewBox: "0 0 24 24", width: 16 },
  name: "xmark-16",
});

interface ModeToggleTipProps {
  /** The button the tip points at. */
  anchor: HTMLElement;
  body: ReactNode;
  /** Accessible name of the close button. */
  closeLabel?: string;
  id: string;
  /** Called by the close button and by Escape; focus then returns to the anchor. */
  onDismiss: () => void;
  title?: ReactNode;
}

// The coachmark with its default props:
// align center, size default, below the anchor. The surface colours are the
// --color-fill-coachmark (--blue-500) and --color-text-coachmark
// (--white); neither depends on the theme.
const popupClasses =
  "group relative z-50 flex w-60 items-start gap-2 rounded-xl bg-(--color-status-info-solid) p-3 text-sm text-white shadow-lg outline-hidden select-none [-webkit-app-region:no-drag]";

// The 36 x 14 arrow, drawn above the surface for side bottom and
// flipped with -scale-y-100.
const arrowClasses =
  "pointer-events-none text-(--color-status-info-solid) absolute left-1/2 hidden h-3.5 w-9 origin-top -translate-x-1/2 overflow-visible group-data-[side=bottom]:top-0 group-data-[side=bottom]:block group-data-[side=bottom]:-scale-y-100 group-data-[side=top]:top-full group-data-[side=top]:block";

const closeButtonClasses =
  "relative flex size-4 shrink-0 cursor-default items-center justify-center rounded-sm before:absolute before:-inset-1 focus-visible:outline-2 focus-visible:outline-current";

// `sideOffset`: 18 for align center, multiplied by the UI scale, which is 1
// without a provider.
const SIDE_OFFSET = 18;
const COLLISION_PADDING = 9;

// A DismissableLayer listens for Escape only in the topmost open layer. The ids of the open tips, oldest
// first, stand for that stack.
const openTipIds: string[] = [];

const useTipLayer = (id: string) => {
  useEffect(() => {
    openTipIds.push(id);

    return () => {
      openTipIds.splice(openTipIds.lastIndexOf(id), 1);
    };
  }, [id]);
};

const ModeToggleTip = ({
  anchor,
  body,
  closeLabel = "Close tooltip",
  id,
  onDismiss,
  title,
}: ModeToggleTipProps) => {
  useTipLayer(id);

  const titleId = `${id}-title`;
  const bodyId = `${id}-body`;

  const dismiss = () => {
    onDismiss();
    anchor.focus();
  };

  return (
    <Popover.Root
      modal={false}
      onOpenChange={(open, details) => {
        // The component ignores presses outside and focus changes
        // (onInteractOutside preventDefault); Escape closes.
        if (
          !open &&
          details.reason === "escape-key" &&
          openTipIds.at(-1) === id
        ) {
          dismiss();
        }
      }}
      open
    >
      <Popover.Portal>
        <Popover.Positioner
          align="center"
          anchor={anchor}
          className="z-50"
          collisionPadding={COLLISION_PADDING}
          side="bottom"
          sideOffset={SIDE_OFFSET}
        >
          <Popover.Popup
            aria-describedby={title === undefined ? undefined : bodyId}
            aria-labelledby={title === undefined ? bodyId : titleId}
            className={popupClasses}
            finalFocus={false}
            id={id}
            initialFocus={false}
          >
            <div className="flex min-w-0 flex-1 flex-col gap-0.5">
              {title === undefined ? null : (
                <div className="font-semibold" id={titleId}>
                  {title}
                </div>
              )}
              <div id={bodyId}>{body}</div>
            </div>
            <button
              aria-label={closeLabel}
              className={closeButtonClasses}
              onClick={(event) => {
                event.stopPropagation();
                dismiss();
              }}
              type="button"
            >
              <CloseIcon />
            </button>
            <svg
              aria-hidden="true"
              className={arrowClasses}
              fill="currentColor"
              viewBox="0 0 36 14"
            >
              <path d="M0 0C8 0 11 3.5 14.5 8.2L16.2 10.5C17.1 11.8 18.9 11.8 19.8 10.5L21.5 8.2C25 3.5 28 0 36 0V-1H0Z" />
            </svg>
          </Popover.Popup>
        </Popover.Positioner>
      </Popover.Portal>
    </Popover.Root>
  );
};

export { ModeToggleTip };

export type { ModeToggleTipProps };

"use client";

// Lucide artwork is covered by components/icon/lucide.license.

import { createIcon } from "@/components/icon";
import { ModeToggleTip } from "@/components/segmented-control/mode-toggle-tip";
import {
  Tooltip,
  TooltipPopup,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { usePrefersReducedMotion } from "@/hooks/use-device";
import { hasReducedMotion } from "@/lib/device";
import { cn } from "@/lib/utils";
/* oxlint-disable shadcn/no-restyle, shadcn/no-arbitrary-values, shadcn/require-static-classes -- The option is a restyled tooltip trigger with measured values that have no theme token (0.5px border, light-dark track, focus ring color). */
import { useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import type { CSSProperties, MouseEvent, ReactNode } from "react";

// The "requires upgrade" mark and its sparkle icon.
const SparkleIcon = createIcon({
  body: '<g fill="currentColor" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M11.017 2.814a1 1 0 0 1 1.966 0l1.051 5.558a2 2 0 0 0 1.594 1.594l5.558 1.051a1 1 0 0 1 0 1.966l-5.558 1.051a2 2 0 0 0-1.594 1.594l-1.051 5.558a1 1 0 0 1-1.966 0l-1.051-5.558a2 2 0 0 0-1.594-1.594l-5.558-1.051a1 1 0 0 1 0-1.966l5.558-1.051a2 2 0 0 0 1.594-1.594z"></path></g>',
  canvas: { height: 12, viewBox: "0 0 24 24", width: 12 },
  name: "sparkle-fill-12",
});

// The indicator offset per option.
// --mode-toggle-sign is 1, or -1 for right to left languages.
const INDICATOR_OFFSETS = [
  "calc((0% - 0px) * var(--mode-toggle-sign))",
  "calc((100% - 17px) * var(--mode-toggle-sign))",
] as const;

// The indicator transition: { duration: 300 / 1e3, ease: [.23, 1, .32, 1] }; the
// indicator class holds the curve and --mode-toggle-duration the time.

// The event that closes open tooltips.
const DISMISS_TOOLTIPS_EVENT = "ui:dismiss-tooltips";

const rootClasses =
  "relative isolate inline-grid h-9 max-w-full min-w-0 grid-cols-2 gap-0 rounded-full select-none [&:has(>button[aria-pressed=true]:focus-visible)>button[aria-pressed=true]:focus-visible]:outline-none [&:has(>button[aria-pressed=true]:focus-visible)>[data-mode-toggle-indicator]]:[outline-color:-webkit-focus-ring-color] [&:has(>button[aria-pressed=true]:focus-visible)>[data-mode-toggle-indicator]]:[outline:auto]";

const trackClasses =
  "pointer-events-none absolute inset-x-px top-1/2 z-0 h-8.5 -translate-y-1/2 rounded-full [background:var(--theme-background-mode-toggle-track)]";

// Right-to-left languages reverse the indicator direction.
const indicatorClasses =
  "pointer-events-none relative z-10 col-start-1 row-start-1 -my-[0.5px] -ms-[0.5px] w-[calc(100%+9px)] [transform:translateX(var(--mode-toggle-x))] [transition:transform_var(--mode-toggle-duration)_cubic-bezier(0.23,1,0.32,1)] rounded-full border-[0.5px] border-(--theme-border-mode-toggle-selected) [background:light-dark(color-mix(in_oklab,var(--ck-palette-surface-control)_90%,transparent),var(--theme-background-mode-toggle-selected))] [box-shadow:var(--shadow-md)] [--mode-toggle-sign:1] [&:is(:lang(ae),:lang(ar),:lang(arc),:lang(bcc),:lang(bqi),:lang(ckb),:lang(dv),:lang(fa),:lang(glk),:lang(he),:lang(ku),:lang(mzn),:lang(nqo),:lang(pnb),:lang(ps),:lang(sd),:lang(ug),:lang(ur),:lang(yi))]:[--mode-toggle-sign:-1]";

// `cursor-interaction` is `default` on the Electron desktop window.
const optionClasses =
  "relative z-10 inline-flex h-full min-w-0 cursor-default items-center justify-center rounded-full px-10 text-sm font-medium whitespace-nowrap @max-xs/home-mode-toggle:px-2.5 disabled:cursor-not-allowed disabled:opacity-40";

const selectedTextClasses = "text-text";

const inactiveTextClasses =
  "text-[color-mix(in_oklab,var(--ck-palette-ink)_80%,transparent)] [&:focus-visible]:text-text [&:hover]:text-text";

const optionPadding = [
  "col-start-1 row-start-1 ps-11 pe-9",
  "col-start-2 row-start-1 ps-9 pe-11",
] as const;

interface ModeToggleOption {
  /** Dot before the label while the option is not selected. */
  discoveryBadge?: boolean;
  /** Accent instead of dimmed text on a locked, unselected option. */
  emphasizeUpgrade?: boolean;
  id: string;
  label: ReactNode;
  /** Shows the upgrade mark and the screen reader suffix. */
  requiresUpgrade?: boolean;
  tooltip: ReactNode;
  /** Screen reader text appended to a locked option. */
  upgradeSuffix?: ReactNode;
}

/** The text of an onboarding tip that points at the second option. */
interface ModeToggleTipContent {
  body: ReactNode;
  /** Accessible name of the tip's close button. */
  closeLabel?: string;
  /**
   * Called when the tip is closed (close button or Escape) and when the second
   * option is pressed. The application stores that decide whether a tip is due
   * are not part of this component: pass the content to show it and drop it
   * from the props in `onDismiss` to hide it.
   */
  onDismiss: () => void;
  title?: ReactNode;
}

interface ModeToggleProps {
  ariaLabel: string;
  autoFocusSelected?: boolean;
  className?: string;
  disabled?: boolean;
  /**
   * The targeted tip of the second option (target tpp-surface-mode-toggle).
   * It shows only while the first option is selected, the toggle is enabled
   * and the second option requires an upgrade.
   */
  onboardingTip?: ModeToggleTipContent;
  /**
   * The post-trial tooltip "Try it for free". It shows only while the
   * first option is selected, the toggle is enabled and the second option does
   * not require an upgrade, and any press outside the option and the tooltip
   * dismisses it.
   */
  noPaymentTrialTooltip?: ModeToggleTipContent;
  onSelectedAutoFocus?: () => void;
  onTransitionComplete?: () => void;
  onValueChange: (id: string) => void;
  options: readonly [ModeToggleOption, ModeToggleOption];
  value: string;
}

const noCleanup = () => {
  /* An effect with nothing to undo. */
};

const dismissTooltips = (event: MouseEvent<HTMLDivElement>) => {
  if (
    event.target instanceof Node &&
    event.currentTarget.contains(event.target)
  ) {
    window.dispatchEvent(new Event(DISMISS_TOOLTIPS_EVENT));
  }
};

const lockedClassName = (option: ModeToggleOption, selected: boolean) => {
  if (option.requiresUpgrade !== true || selected) {
    return "";
  }

  return option.emphasizeUpgrade === true
    ? "text-text-notice"
    : "text-text-subtle";
};

const OptionLabel = ({
  option,
  selected,
}: {
  option: ModeToggleOption;
  selected: boolean;
}) => {
  const locked = option.requiresUpgrade === true;

  return (
    <span
      className={cn(
        "relative inline-flex items-center gap-1",
        lockedClassName(option, selected)
      )}
    >
      {option.discoveryBadge === true && !locked && !selected ? (
        <span
          aria-hidden="true"
          className="absolute end-full top-1/2 me-2 size-1.25 -translate-y-1/2 rounded-full bg-fill-info-solid"
        />
      ) : null}
      {locked ? <SparkleIcon /> : null}
      {option.label}
      {locked && option.upgradeSuffix !== undefined ? (
        <span className="sr-only">{option.upgradeSuffix}</span>
      ) : null}
    </span>
  );
};

// `initial` is the other option while the toggle autofocuses the selected
// option, so the indicator slides in on mount. A change of option, or the
// first placement without that slide, completes at once under reduced motion
// and otherwise when the transition ends.
const useIndicator = (
  selectedIndex: number,
  autoFocusSelected: boolean,
  onTransitionComplete: (() => void) | undefined
) => {
  const indicatorRef = useRef<HTMLSpanElement | null>(null);
  const mountedRef = useRef(false);
  const completeRef = useRef(onTransitionComplete);

  useEffect(() => {
    completeRef.current = onTransitionComplete;
  });

  useLayoutEffect(() => {
    const indicator = indicatorRef.current;

    if (indicator === null) {
      return;
    }

    const first = !mountedRef.current;

    mountedRef.current = true;

    // The store value is the server snapshot while hydrating, so ask the
    // browser.
    const reduced = hasReducedMotion();
    const slidesIn = first && autoFocusSelected && !reduced;

    if (slidesIn) {
      indicator.style.transition = "none";
      indicator.style.setProperty(
        "--mode-toggle-x",
        INDICATOR_OFFSETS[selectedIndex === 0 ? 1 : 0]
      );
      indicator.getBoundingClientRect();
      indicator.style.transition = "";
      indicator.style.setProperty(
        "--mode-toggle-x",
        INDICATOR_OFFSETS[selectedIndex]
      );
    }

    if (reduced || (first && !slidesIn)) {
      completeRef.current?.();
    }
  }, [autoFocusSelected, selectedIndex]);

  useEffect(() => {
    const indicator = indicatorRef.current;

    if (indicator === null) {
      return noCleanup;
    }

    const handleEnd = (event: TransitionEvent) => {
      if (event.target === indicator && event.propertyName === "transform") {
        completeRef.current?.();
      }
    };

    indicator.addEventListener("transitionend", handleEnd);

    return () => {
      indicator.removeEventListener("transitionend", handleEnd);
    };
  }, []);

  return indicatorRef;
};

// The no-payment trial tooltip:
// a press outside the option and the tooltip dismisses it. The listener is
// on the document in the capture phase.
const useOutsidePressDismiss = (
  anchor: HTMLElement | null,
  tooltipId: string,
  active: boolean,
  onDismiss: (() => void) | undefined
) => {
  const dismissRef = useRef(onDismiss);

  useEffect(() => {
    dismissRef.current = onDismiss;
  });

  useEffect(() => {
    if (!active || anchor === null) {
      return noCleanup;
    }

    const { ownerDocument } = anchor;

    const handlePointerDown = (event: PointerEvent) => {
      const { target } = event;

      if (
        target instanceof Node &&
        (anchor.contains(target) ||
          ownerDocument
            .querySelector(`#${CSS.escape(tooltipId)}`)
            ?.contains(target) === true)
      ) {
        return;
      }

      dismissRef.current?.();
    };

    ownerDocument.addEventListener("pointerdown", handlePointerDown, true);

    return () => {
      ownerDocument.removeEventListener("pointerdown", handlePointerDown, true);
    };
  }, [active, anchor, tooltipId]);
};

// The two-option "Composer mode" toggle: pressed buttons over one sliding indicator.
const ModeToggle = ({
  ariaLabel,
  autoFocusSelected = false,
  className,
  disabled = false,
  noPaymentTrialTooltip,
  onboardingTip,
  onSelectedAutoFocus,
  onTransitionComplete,
  onValueChange,
  options,
  value,
}: ModeToggleProps) => {
  const reducedMotion = usePrefersReducedMotion();
  const selectedIndex = options[1].id === value ? 1 : 0;
  const tipId = useId();
  const trialId = useId();

  const [secondButton, setSecondButton] = useState<HTMLButtonElement | null>(
    null
  );

  // The component shows the targeted tip when the first option is selected,
  // the toggle is enabled and the second option needs an upgrade, once
  // its anchor exists. The trial tooltip takes the same
  // conditions with the second option not needing an upgrade.
  const firstSelected = selectedIndex === 0 && !disabled;
  const secondRequiresUpgrade = options[1].requiresUpgrade === true;
  const anchored = firstSelected && secondButton !== null;
  const tip = anchored && secondRequiresUpgrade ? onboardingTip : undefined;

  const trial =
    anchored && !secondRequiresUpgrade ? noPaymentTrialTooltip : undefined;

  const handleTipDismiss = () => {
    tip?.onDismiss();
  };

  const handleTrialDismiss = () => {
    trial?.onDismiss();
  };

  let describedBy: string | undefined;

  if (trial !== undefined) {
    describedBy = trialId;
  } else if (tip !== undefined) {
    describedBy = tipId;
  }

  useOutsidePressDismiss(
    secondButton,
    trialId,
    trial !== undefined,
    handleTrialDismiss
  );

  const indicatorRef = useIndicator(
    selectedIndex,
    autoFocusSelected,
    onTransitionComplete
  );

  const indicatorStyle: CSSProperties & Record<`--${string}`, string> = {
    "--mode-toggle-duration": reducedMotion ? "0s" : "300ms",
    "--mode-toggle-x": INDICATOR_OFFSETS[selectedIndex],
  };

  return (
    <div
      aria-label={ariaLabel}
      className={cn(rootClasses, className)}
      onClickCapture={dismissTooltips}
      // The group is <div role="group" aria-label>.
      // oxlint-disable-next-line jsx-a11y/prefer-tag-over-role
      role="group"
    >
      <span aria-hidden="true" className={trackClasses} />
      <span
        aria-hidden="true"
        className={indicatorClasses}
